use super::*;
use std::vec::Vec;

#[test]
fn baud_plans_match_original_sdk_helpers_for_all_ports_and_clock_profiles() {
    // Native original C outputs generated by hisi-registers checker, not HAL.
    for row in include_str!("sdk-config.txt").lines().filter(|row| !row.starts_with('#')) {
        let v: Vec<u32> = row.split_whitespace().map(|s| s.parse().unwrap()).collect();
        let config =
            LineConfig::new(NonZeroU32::new(v[1]).unwrap(), v[2], DataBits::Eight, Parity::None, StopDuration::One);
        if v[8] == 0 {
            assert!(config.is_none());
            continue;
        }
        let c = config.unwrap();
        assert_eq!([u32::from(c.integer & 255), u32::from(c.integer >> 8), u32::from(c.fraction)], v[3..6]);
        assert_eq!(u32::from(c.sampling - 1) | (u32::from(c.sampling / 2 - 1) << 4), v[6] & 255);
        assert_eq!(c.clock_hz().get(), v[1]);
        assert_eq!(c.requested_baud().get(), v[2]);
        assert!(c.actual_baud() >= v[2]); // SDK floors the divisor, not the baud.
    }
}

#[test]
fn boundary_inputs_reject_zero_divisors_and_never_overflow() {
    for hz in [1, 8, 16, 32_000_000, u32::MAX] {
        for baud in [0, 1, hz / 16, hz / 8, hz / 8 + 1, 1 << 28, u32::MAX] {
            let c =
                LineConfig::new(NonZeroU32::new(hz).unwrap(), baud, DataBits::Eight, Parity::None, StopDuration::One);
            if let Some(c) = c {
                assert_ne!(c.integer, 0);
                assert!(c.fraction < 64);
                assert!(c.actual_baud() >= baud);
                assert!(u64::from(baud) * 8 <= u64::from(hz));
            } else if baud > 0 && u64::from(baud) * 16 <= u64::from(hz) {
                assert!(u64::from(hz) / (u64::from(baud) * 16) > 65535);
            }
        }
    }
}

#[test]
fn stop_duration_combinations_are_physical_not_misleading_bit_labels() {
    for data in [DataBits::Five, DataBits::Six, DataBits::Seven, DataBits::Eight] {
        for parity in [Parity::None, Parity::Even, Parity::Odd] {
            for stop in [StopDuration::One, StopDuration::OneAndHalf, StopDuration::Two] {
                let valid =
                    stop == StopDuration::One || ((data == DataBits::Five) == (stop == StopDuration::OneAndHalf));
                let c = LineConfig::new(NonZeroU32::new(32_000_000).unwrap(), 115200, data, parity, stop);
                assert_eq!(c.is_some(), valid);
            }
        }
    }
}

#[test]
fn divisor_access_is_closed_before_the_independent_settle_delay() {
    #[derive(Default)]
    struct Mock {
        open: bool,
        ready: bool,
        steps: Vec<u8>,
    }
    impl Registers for Mock {
        fn frame(&mut self, _: LineConfig) {
            assert!(!self.open);
            self.steps.push(0);
        }
        fn sampling(&mut self, _: u8) {
            self.steps.push(1);
        }
        fn divisor_access(&mut self, enabled: bool) {
            self.open = enabled;
            self.steps.push(if enabled { 2 } else { 4 });
        }
        fn divisor(&mut self, _: u16, _: u8) {
            assert!(self.open);
            self.ready = true;
            self.steps.push(3);
        }
    }
    struct Delay(u32);
    impl DelayNs for Delay {
        fn delay_ns(&mut self, ns: u32) {
            self.0 += ns;
        }
    }
    let c =
        LineConfig::new(NonZeroU32::new(32_000_000).unwrap(), 115200, DataBits::Eight, Parity::None, StopDuration::One)
            .unwrap();
    let mut io = Mock::default();
    let mut delay = Delay(0);
    apply(&mut io, c, &mut delay);
    assert!(io.ready && !io.open);
    assert_eq!(io.steps, [0, 1, 2, 3, 4]);
    assert_eq!(delay.0, 10_000);
}
